namespace LightAlarm {

// Fixed RAM ring. Keeping insertion/indexing separate from networking makes
// capacity, rollover and chronological pagination testable on the host.
template<typename T, uint8_t Capacity> class LogRing {
  static_assert(Capacity > 0, "A log ring needs storage");
  T _entries[Capacity];
  uint8_t _head = 0, _size = 0;
  uint32_t _generation = 0;
public:
  static constexpr uint8_t CAPACITY = Capacity;
  uint8_t size() const { return _size; }
  uint32_t generation() const { return _generation; }
  void append(const T& entry) {
    _entries[_head] = entry;
    _head = (_head + 1) % Capacity;
    if (_size < Capacity) ++_size;
    ++_generation;
  }
  const T* newest(uint8_t age) const {
    return age < _size ? &_entries[(_head + Capacity - 1 - age) % Capacity] : nullptr;
  }
};

} // namespace LightAlarm
